import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";

import {
  GENERATED_CURRICULUM_ROOT,
  PUBLIC_ROOT,
  REPOSITORY_ROOT,
} from "../lib/paths.js";

globalThis.window = {};
await import(pathToFileURL(path.join(PUBLIC_ROOT, "content/exercise-data.js")));

const course = globalThis.window.COURSE_DATA;
const solutionCode = {};

for (const chapter of course.chapters) {
  for (const exercise of chapter.exercises) {
    solutionCode[exercise.id] = await readFile(
      path.join(REPOSITORY_ROOT, exercise.file),
      "utf8"
    );
  }
}

const banner = "// Generated by scripts/build/build-solution-bundle.js. Do not edit by hand.\n";
const output = `${banner}window.SOLUTION_CODE = ${JSON.stringify(solutionCode, null, 2)};\n`;

await writeFile(
  path.join(GENERATED_CURRICULUM_ROOT, "solution-code.js"),
  output,
  "utf8"
);
console.log(`Bundled ${Object.keys(solutionCode).length} Python solutions.`);
